//! MBRXC root-finder for CubeCL kernels.
//!
//! Implements `xc_mgga_x_mbrxc_get_x(Q)` which solves
//!   (1+x)^(5/3) * exp(-2x/3) - rhs * (x - 3) = 0
//! via inlined Brent's method. Called by `mgga_x_mbrxc_bg` and `mgga_x_mggac`.
//!
//! Translated from libxc `mgga_x_mbrxc_bg.c` and `math_brent.c`. Mirrors the
//! structure of `br89.rs`: 60 unrolled Brent iterations because CubeCL does
//! not support dynamic loops, function pointers, or tuple returns from helpers.

#![allow(
    clippy::excessive_precision,
    clippy::too_many_arguments,
    unused_variables,
    non_snake_case,
)]


// `rmath` below is `crate::rmath` -- this crate's BitExact surface, not the
// upstream crate, whose free functions are deliberately the Fast path.
use crate::rmath;

/// (32 * pi)^(2/3) — precomputed constant used in the rhs formula.
const POW_32PI_TWO_THIRDS: f64 = 21.620541520507917;

/// Evaluate the MBRXC objective: f(x) = (1+x)^(5/3) * exp(-2x/3) - rhs*(x-3).
fn mbrxc_obj(x: f64, rhs: f64) -> f64 {
    let xm3 = x - 3.0_f64;
    let arg = 2.0_f64 * x / 3.0_f64;
    // Guard exp underflow: for arg > ~115, exp(-arg) is below f64 subnormal min.
    let eee = (if arg <= 115.12925464970228_f64 { rmath::exp(-arg) } else { 0.0_f64 });
    let one_plus_x = 1.0_f64 + x;
    let pow53 = rmath::pow(one_plus_x, 5.0_f64 / 3.0_f64);
    pow53 * eee - rhs * xm3
}

